on conflict (id) do update set product_id = excluded.product_id, sku = excluded.sku, label = excluded.label, options = excluded.options, swatch = excluded.swatch, price = excluded.price, compare_at_price = excluded.compare_at_price, stock = excluded.stock, materials = excluded.materials, dimensions = excluded.dimensions, sort_order = excluded.sort_order;

on conflict (code) do update set kind = excluded.kind, value = excluded.value, min_subtotal = excluded.min_subtotal, min_items = excluded.min_items, max_discount = excluded.max_discount, expires_at = excluded.expires_at;
